import{_ as e,o,c as a,ag as s}from"./chunks/framework.BIas3y6W.js";const u=JSON.parse('{"title":"Week 5 Lab — Spec First","description":"","frontmatter":{"source":"weeks/05-spec-first/lab.md"},"headers":[],"relativePath":"weeks/05-spec-first/lab.md","filePath":"weeks/05-spec-first/lab.md"}'),r={name:"weeks/05-spec-first/lab.md"};function i(n,t,d,h,l,c){return o(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="week-5-lab--spec-first" tabindex="-1">Week 5 Lab — Spec First <a class="header-anchor" href="#week-5-lab--spec-first" aria-label="Permalink to &quot;Week 5 Lab — Spec First&quot;">​</a></h1><p><strong>AI-use key:</strong> 🟢 AI on: use AI freely · 🟡 AI limited: the AI may comment or hint, but the work is yours · 🔴 AI off: close the AI tabs and work alone.</p><p>This week you write the spec for <strong>Project 1: A Tool I&#39;d Actually Use</strong>. In <strong>Studio A</strong> you size your idea and write <code>SPEC.md</code> by hand. In <strong>Studio B</strong> a classmate reviews it, a fresh AI that has never heard of you says what it can&#39;t understand (the Goldfish test), and the spec moves into its own repository. Next week an app builder builds from it, and then you do.</p><p><strong>You need:</strong> your paper sketch (or paper and a pen), a laptop, your GitHub account, a chat assistant, and Canvas, the course&#39;s learning management system.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Nothing in your spec should be personal data: not yours, and not anyone else&#39;s. In Studio B you paste it into an AI, and next week into app builders. On some free tiers, including Google AI Studio&#39;s, human reviewers may read what you type (<a href="./../../TOOLS.html">Tool Handout</a>). Your spec describes a tool, not a person.</p></div><p>Using a screen reader or only a keyboard? See the <a href="./../../resources/accessibility.html">screen reader and keyboard guide</a>. Working alone? Each pair activity has a <strong>Working alone?</strong> line.</p><hr><h2 id="studio-a--write-your-spec-75-min" tabindex="-1">Studio A — Write your spec (75 min) <a class="header-anchor" href="#studio-a--write-your-spec-75-min" aria-label="Permalink to &quot;Studio A — Write your spec (75 min)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time</th><th>Part</th><th>AI use</th><th>Core or if time</th></tr></thead><tbody><tr><td>0:00–0:30</td><td>Recap, concept talk and live demo</td><td>—</td><td></td></tr><tr><td>0:30–0:35</td><td><a href="#part-1--size-your-project-1-idea-5-min">Part 1 — Size your idea</a></td><td>🔴 AI off</td><td>Core</td></tr><tr><td>0:35–1:10</td><td><a href="#part-2--write-specmd-yourself-35-min">Part 2 — Write SPEC.md</a></td><td>🔴 AI off</td><td>Core</td></tr><tr><td>1:10–1:15</td><td><a href="#checkpoint-share-5-min">Checkpoint share</a></td><td></td><td></td></tr></tbody></table><h3 id="part-1--size-your-project-1-idea-5-min" tabindex="-1">Part 1 — Size your Project 1 idea (5 min) <a class="header-anchor" href="#part-1--size-your-project-1-idea-5-min" aria-label="Permalink to &quot;Part 1 — Size your Project 1 idea (5 min)&quot;">​</a></h3><p><strong>Why:</strong> a tool you would really use gives you a real user to design for (you) and a reason to finish.</p><p>Project 1 has four fixed rules:</p><ol><li><strong>Single user.</strong> Only you use it. No sharing, no other people&#39;s accounts.</li><li><strong>Data saved in the browser</strong> with <a href="./../../resources/glossary.html#localstorage">localStorage</a> (the browser&#39;s small built-in storage for one website). Nothing goes to a server.</li><li><strong>No login.</strong></li><li><strong>No real personal data about other people.</strong> Use made-up names if you need any.</li></ol><p>Read this list before class. Pick one idea from it, or bring your own that follows the rules.</p><table tabindex="0"><thead><tr><th>Idea</th><th>What it does</th><th>Good edge cases to think about</th></tr></thead><tbody><tr><td>Habit tracker</td><td>Tick off daily habits; show a streak</td><td>Missing a day; a new day starting at midnight</td></tr><tr><td>Plant watering tracker</td><td>List plants and how often they need water; show &quot;water today&quot;</td><td>A plant added today; changing the schedule</td></tr><tr><td>Workout log</td><td>Record exercises, sets and reps; show personal bests</td><td>A zero or negative weight; two bests on one day</td></tr><tr><td>Flashcards</td><td>Make cards for a subject; sort into &quot;know&quot; and &quot;still learning&quot;</td><td>An empty deck; a very long answer</td></tr><tr><td>Recipe box and weekly meal plan</td><td>Save recipes; pick them into days</td><td>A recipe used twice; deleting a recipe that&#39;s planned</td></tr><tr><td>Packing list</td><td>Reusable lists for trips; tick items off</td><td>Resetting ticks for the next trip; duplicate items</td></tr><tr><td>Watch list</td><td>Films and series to watch; mark watched; rate</td><td>Duplicate titles; rating out of range</td></tr><tr><td>Vocabulary builder</td><td>Words and translations; a quick self-quiz</td><td>Accents and special characters; an empty list</td></tr><tr><td>Spending diary</td><td>Your own spending (or made-up numbers) by category, per month</td><td>Decimals like 0.10 + 0.20; a new month</td></tr><tr><td>Mood or energy journal</td><td>Rate 1–5 with a short note, just for you</td><td>Two entries on one day; a very long note</td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Size check.</strong> A good Project 1 has <strong>one main screen</strong> and <strong>3–5 MUST stories</strong>, and you could explain the whole idea in one breath. Save these for later projects: logins and sharing (weeks 11–14), anything that calls the internet or an AI (weeks 9–10), payments (never), photo uploads (the browser&#39;s storage is too small).</p></div><p>Tell your neighbor your idea in one breath. If it takes two, cut something.</p><p>✅ <strong>Checkpoint:</strong> you can finish this sentence out loud: &quot;It&#39;s a tool that helps me [do what] so that [why it matters].&quot;</p><h3 id="part-2--write-specmd-yourself-35-min" tabindex="-1">Part 2 — Write SPEC.md yourself (35 min) <a class="header-anchor" href="#part-2--write-specmd-yourself-35-min" aria-label="Permalink to &quot;Part 2 — Write SPEC.md yourself (35 min)&quot;">​</a></h3><p>🔴 <strong>AI off.</strong> The spec is your thinking. The AI gets to question it in Studio B, but not to write it. Close every AI tab, and switch off any writing assistant built into your notes app or document editor.</p><p><strong>Why:</strong> everyone and everything that reads your spec next can only build what it says.</p><ol><li>Open the <a href="./../../templates/SPEC.html">SPEC template</a> and copy all of its text. On GitHub, use the <strong>Copy raw file</strong> button at the top right of the file; on the course website, use the template&#39;s copy button.</li><li>Paste it somewhere you can keep it until Studio B: a notes app, a document or a text editor. (It goes into your repository in Part 5.)</li><li>Fill in the sections in this order. Use the times as a guide.</li></ol><table tabindex="0"><thead><tr><th>Section</th><th>Time</th><th>Tips</th></tr></thead><tbody><tr><td><strong>1. Problem</strong> and <strong>2. User</strong></td><td>5 min</td><td>Be specific: when, where, how often, what annoys you now. The user can be you</td></tr><tr><td><strong>3. User stories</strong></td><td>7 min</td><td><em>As a …, I want to …, so that …</em> Mark each <strong>MUST</strong> (useless without it), <strong>SHOULD</strong> (want it soon) or <strong>COULD</strong> (nice later). Aim for 3–5 MUSTs</td></tr><tr><td><strong>4. Acceptance criteria</strong></td><td>12 min</td><td>At least one per MUST story, plus at least <strong>two edge cases</strong>. How to write them is below</td></tr><tr><td><strong>5. Out of scope</strong> and <strong>6. Constraints</strong></td><td>5 min</td><td>Name what an AI is likely to add on its own: login, sync, charts, dark mode. Keep the Project 1 constraints: plain HTML, CSS and JavaScript (<code>index.html</code>, <code>style.css</code>, <code>app.js</code>, with the rules in their own module so they can be tested), localStorage, no frameworks, no build step</td></tr><tr><td><strong>7. Wireframe</strong></td><td>3 min</td><td>Describe your paper sketch from top to bottom in a short list (for example &quot;title; input box with Add button; the list, newest first&quot;). A list is easier for screen readers and for AIs than a text drawing</td></tr><tr><td><strong>8. Open questions</strong></td><td>3 min</td><td>Anything you haven&#39;t decided. Write your current best guess next to each one</td></tr></tbody></table><h4 id="how-to-write-an-acceptance-criterion" tabindex="-1">How to write an acceptance criterion <a class="header-anchor" href="#how-to-write-an-acceptance-criterion" aria-label="Permalink to &quot;How to write an acceptance criterion&quot;">​</a></h4><p>An <strong><a href="./../../resources/glossary.html#acceptance-criterion">acceptance criterion</a></strong> says exactly what the app must do in one situation, so anyone can check it by using the app. This course writes them as:</p><p><strong>WHEN</strong> <em>a situation or action</em>, <strong>THE APP SHALL</strong> <em>an observable result</em>.</p><table tabindex="0"><thead><tr><th>Untestable (a vibe)</th><th>Testable (a criterion)</th></tr></thead><tbody><tr><td>The app should be easy to use.</td><td>WHEN I open the app for the first time, THE APP SHALL show &quot;No plants yet. Add your first plant above.&quot;</td></tr><tr><td>Watering works properly.</td><td>WHEN I press <strong>Watered</strong> on a plant, THE APP SHALL move its next watering date forward by its schedule (for example, 3 days) and remove it from the &quot;Water today&quot; list.</td></tr><tr><td>It saves stuff.</td><td>WHEN I reload the page, THE APP SHALL show the same plants and dates as before.</td></tr><tr><td>It handles bad input.</td><td>WHEN I press <strong>Add</strong> with an empty name, THE APP SHALL add nothing and SHALL show &quot;Give your plant a name.&quot;</td></tr></tbody></table><p>Check every criterion against these four questions:</p><ul><li>☐ Could a stranger check it in under a minute, by using the app, without asking me anything?</li><li>☐ Does it say what they would <strong>see</strong> (exact text in quotes where it matters)?</li><li>☐ Does it describe <strong>one</strong> behavior? (Split &quot;and also&quot; into two criteria.)</li><li>☐ Across the whole table, have I covered at least two edge cases? Try: empty input · very long input · duplicates · reloading the page · a small phone screen · zero or negative numbers · midnight or a new week · deleting the last item.</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>If you already program:</strong> say what, not how. Leave functions, classes and data structures out of the spec; a criterion describes what the user sees. Do use your instinct for boundaries: &quot;WHEN I type a name of exactly 40 characters, THE APP SHALL accept it; WHEN I type 41, THE APP SHALL refuse it&quot; is a sharp pair of criteria, and next week each becomes a one-line automated test.</p></div><p>Compare your draft with the <a href="./example-spec.html">example spec</a> and its &quot;Why this spec works&quot; table.</p><p>✅ <strong>Checkpoint:</strong> every section is filled in, with 3–5 MUST stories, at least 5 acceptance criteria (at least two of them edge cases), and at least 3 out-of-scope items.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Finding this hard is normal. In CMU&#39;s AI coding course, students rated writing the spec as harder than managing AI agents (<a href="https://www.cs.cmu.edu/~113/bestPractices.html" target="_blank" rel="noreferrer">CMU 15-113</a>). It gets easier with every project.</p></div><h3 id="checkpoint-share-5-min" tabindex="-1">Checkpoint share (5 min) <a class="header-anchor" href="#checkpoint-share-5-min" aria-label="Permalink to &quot;Checkpoint share (5 min)&quot;">​</a></h3><p>Two or three volunteers read out one criterion. The room applies the stranger test: could you check it in a minute without asking? If not, say what&#39;s missing.</p><p><strong>Before you leave Studio A:</strong></p><ul><li>☐ Your <code>SPEC.md</code> draft is saved somewhere you can open in Studio B.</li><li>☐ Not finished? Finish it before Studio B, still 🔴 AI off. Studio B starts with the review.</li></ul><h3 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Problem</th><th>Try this</th></tr></thead><tbody><tr><td>I can&#39;t choose between two ideas</td><td>Choose the one you&#39;d use this week. Then apply the size check: one screen, 3–5 MUSTs</td></tr><tr><td>My idea needs a login, sharing or live data</td><td>Cut it to the single-user core and put the rest in Out of scope. The big version may make a good capstone (<a href="./../../projects/capstone-ideas.html">capstone ideas</a>)</td></tr><tr><td>My criteria say &quot;fast&quot;, &quot;nice&quot; or &quot;properly&quot;</td><td>Ask the stranger question: what would they <strong>see</strong>? Write that, in quotes</td></tr><tr><td>I can&#39;t think of edge cases</td><td>Go down the edge-case list above, or ask: &quot;What&#39;s the first thing a careless user would do?&quot;</td></tr><tr><td>My spec is running onto a second page</td><td>Too big. Move SHOULD and COULD criteria to later and keep the MUSTs</td></tr><tr><td>The pasted template lost its tables</td><td>Copy the raw file (the <strong>Copy raw file</strong> button), not the rendered page</td></tr></tbody></table><hr><h2 id="studio-b--review-and-test-your-spec-75-min" tabindex="-1">Studio B — Review and test your spec (75 min) <a class="header-anchor" href="#studio-b--review-and-test-your-spec-75-min" aria-label="Permalink to &quot;Studio B — Review and test your spec (75 min)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time</th><th>Part</th><th>AI use</th><th>Core or if time</th></tr></thead><tbody><tr><td>0:00–0:05</td><td>Show and tell: one criterion, before and after the stranger test</td><td>—</td><td></td></tr><tr><td>0:05–0:30</td><td><a href="#part-3--peer-spec-review-25-min">Part 3 — Peer spec review</a></td><td>🔴 AI off</td><td>Core</td></tr><tr><td>0:30–0:50</td><td><a href="#part-4--the-goldfish-test-20-min">Part 4 — The Goldfish test</a></td><td>🟡 AI limited</td><td>Core</td></tr><tr><td>0:50–1:05</td><td><a href="#part-5--give-your-spec-a-home-15-min">Part 5 — Give your spec a home</a></td><td>none needed</td><td>Core</td></tr><tr><td>(when Part 5 is done)</td><td><a href="#part-6--polish-the-spec-10-min">Part 6 — Polish the spec</a></td><td>🔴 AI off / 🟡 AI limited</td><td>If time</td></tr><tr><td>1:05–1:15</td><td><a href="#exit-ticket-10-min">Exit ticket</a></td><td>🔴 AI off</td><td></td></tr></tbody></table><h3 id="part-3--peer-spec-review-25-min" tabindex="-1">Part 3 — Peer spec review (25 min) <a class="header-anchor" href="#part-3--peer-spec-review-25-min" aria-label="Permalink to &quot;Part 3 — Peer spec review (25 min)&quot;">​</a></h3><p>🔴 <strong>AI off.</strong> This review is graded (<a href="./../../assessment/rubrics.html#reflections-and-peer-reviews">peer review rubric</a>): it&#39;s specific, accurate and kind.</p><p><strong>Why:</strong> a classmate reads your spec the way a builder will, without the picture in your head.</p><ol><li><strong>Swap (5 min).</strong> Swap laptops with your partner, or share a view-only link. Read their spec silently.</li><li><strong>Talk (10 min, 5 per spec).</strong> The reviewer does three things while the author stays silent and notes every surprise: <ul><li><strong>Predict:</strong> without looking at the wireframe, describe the app you would build from this spec.</li><li><strong>Find the untestable:</strong> point at any criterion (by ID) you couldn&#39;t check by using the app, and say why.</li><li><strong>Find the missing edge:</strong> name one situation the spec doesn&#39;t cover.</li></ul></li><li><strong>Write it up on Canvas (10 min).</strong> Open the <strong>Week 5 spec review</strong> assignment and write your review of your partner&#39;s spec under five headings: your prediction; every untestable criterion (by ID) and why; one missing edge case; one strength; one question for the author. Refer to your partner by GitHub username. Share it with them privately (a Canvas comment), never as a file, issue or comment in their repository. Not finished? Finish it by the homework deadline.</li></ol><p>Authors: fix what you agree with now, or add it to &quot;Open questions&quot;. Note what changed for your <code>PROMPTS.md</code> (write &quot;my review partner&quot;, not a name).</p><p>✅ <strong>Checkpoint:</strong> you&#39;ve given a review and received one, and your spec has changed in at least one place.</p><p><strong>Working alone?</strong> Ask your instructor for the practice spec; your written review of it is the graded one. Then read your own spec aloud as if you were a stranger, or ask a friend to predict the app from it.</p><h3 id="part-4--the-goldfish-test-20-min" tabindex="-1">Part 4 — The Goldfish test (20 min) <a class="header-anchor" href="#part-4--the-goldfish-test-20-min" aria-label="Permalink to &quot;Part 4 — The Goldfish test (20 min)&quot;">​</a></h3><p>🟡 <strong>AI limited.</strong> The AI reads your spec and asks questions. It doesn&#39;t rewrite your spec, and you don&#39;t paste back anything it writes.</p><p><strong>Why:</strong> a fresh chat knows nothing about you, your idea or this class, like a goldfish that remembers nothing. Every app builder, chat assistant and agent that reads your spec starts that way. If a fresh chat can&#39;t understand your spec without asking you, neither can they.</p><ol><li><p><strong>Open a brand-new chat</strong> in your chat assistant (Gemini, or a fallback from the <a href="./../../TOOLS.html">Tool Handout</a>): no earlier messages, and no explanation of your idea. If your assistant remembers past conversations, use a temporary chat.</p></li><li><p><strong>Paste this prompt, then your spec, and nothing else:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Tell me what is unclear in the spec below. Do NOT rewrite it and do NOT write any code.</span></span>
<span class="line"><span>Context: The spec below is all you know. Later you will have to build the app from it, with no chance to ask me anything.</span></span>
<span class="line"><span>Constraints: Reply with three short lists. &quot;What I would build&quot;: the app in 5 bullet points, as you understand it. &quot;Questions I&#39;d have to ask&quot;: up to 6 questions the spec doesn&#39;t answer. &quot;Guesses I&#39;d make&quot;: up to 4 assumptions you would have to make, each with the criterion ID or section it affects. Don&#39;t suggest new features and don&#39;t write criteria for me.</span></span>
<span class="line"><span>Done when: I can compare your picture of the app with mine, and every question points to a part of my spec.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[paste your whole SPEC.md here]</span></span></code></pre></div></li><li><p><strong>Compare (4 min).</strong> Read &quot;What I would build&quot;. Mark every place it differs from the app in your head. Each question and each guess is a gap in your spec.</p></li><li><p><strong>Log it (4 min).</strong> In your notes, write this entry. It becomes your first <code>PROMPTS.md</code> entry in Part 5, and the <a href="./../../assessment/rubrics.html#project-1">Project 1 rubric</a> looks for it.</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">date</span><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">] — Goldfish test of SPEC.md</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **Tool:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [chat assistant], fresh chat, spec only</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **What it asked or got wrong:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [for example: &quot;Does the week start on Monday?&quot; (AC7)]</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **What I changed in SPEC.md:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [for example: AC7 now says Monday to Sunday]</span></span></code></pre></div></li><li><p><strong>Revise (8 min).</strong> Answer each question <strong>in the spec</strong>, in your own words, not in the chat. A feature you decide not to build goes into Out of scope.</p></li></ol><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>If the AI rewrites your spec anyway, don&#39;t use its version. Reply &quot;Please only list questions; don&#39;t rewrite.&quot; The course&#39;s AI policy lets an AI critique your spec, not write it.</p></div><p>✅ <strong>Checkpoint:</strong> your Goldfish log names at least two questions or wrong guesses, and your spec has changed in at least two places since Studio A (from the peer review and the Goldfish test).</p><h3 id="part-5--give-your-spec-a-home-15-min" tabindex="-1">Part 5 — Give your spec a home (15 min) <a class="header-anchor" href="#part-5--give-your-spec-a-home-15-min" aria-label="Permalink to &quot;Part 5 — Give your spec a home (15 min)&quot;">​</a></h3><p><strong>Why:</strong> from now on your spec lives in the same repository as your code, so every tool you use can read it and your changes have a history.</p><ol><li><strong>Create the repository.</strong> On GitHub, click <strong>+</strong> → <strong>New repository</strong>. Name it after your tool, in lowercase with hyphens (for example <code>plant-tracker</code>). Choose <strong>Public</strong> and tick <strong>Add a README file</strong>. Click <strong>Create repository</strong>.</li><li><strong>Add your spec.</strong> Click <strong>Add file</strong> → <strong>Create new file</strong>. Name it <code>SPEC.md</code>, paste your spec, and commit with the message <code>Add spec</code>.</li><li><strong>Start your prompt log.</strong> Copy the <a href="./../../templates/PROMPTS.html">PROMPTS template</a> the same way you copied the SPEC template, and create a file called <code>PROMPTS.md</code>. Paste in your Goldfish log from Part 4, and one line saying what changed after the peer review. Commit with the message <code>Start prompt log</code>.</li><li><strong>Turn on GitHub Pages now,</strong> so it&#39;s ready next week. Go to <strong>Settings</strong> → <strong>Pages</strong>. Under &quot;Build and deployment&quot;, choose <strong>Deploy from a branch</strong>, then branch <strong>main</strong> and folder <strong>/ (root)</strong>, and click <strong>Save</strong>. Menus move. If you can&#39;t find it, ask your chat assistant where the GitHub Pages setting is.</li></ol><p>Your repository is public, so it holds only your project work: no classmates&#39; names, no grades, no reflections. Those go on Canvas.</p><p>✅ <strong>Checkpoint:</strong> your repository shows <code>README.md</code>, <code>SPEC.md</code> and <code>PROMPTS.md</code>, and <strong>Settings → Pages</strong> shows your site address (it shows your README until you add <code>index.html</code> next week).</p><h3 id="part-6--polish-the-spec-10-min" tabindex="-1">Part 6 — Polish the spec (10 min) <a class="header-anchor" href="#part-6--polish-the-spec-10-min" aria-label="Permalink to &quot;Part 6 — Polish the spec (10 min)&quot;">​</a></h3><p><strong>If time.</strong> Pick one:</p><ul><li><strong>Add your wireframe image.</strong> Take a screenshot of your sketch photo (a screenshot carries no location data) and save it as <code>wireframe.png</code>. On your repository page, click <strong>Add file</strong> → <strong>Upload files</strong>, drop it in, and commit. Then edit <code>SPEC.md</code> and add <code>![Wireframe: (one-line description)](wireframe.png)</code> to section 7, keeping your top-to-bottom list.</li><li><strong>Goldfish, round 2.</strong> Run Part 4 again in another brand-new chat with your revised spec. Does it ask fewer questions? Log the count. (This is homework anyway.)</li><li><strong>Start your logic plan.</strong> Read <a href="./homework.html#4-write-a-logic-plan-1-hour">homework task 4</a> and mark which of your criteria hide a rule: a check on input, a calculation, a date.</li></ul><h3 id="exit-ticket-10-min" tabindex="-1">Exit ticket (10 min) <a class="header-anchor" href="#exit-ticket-10-min" aria-label="Permalink to &quot;Exit ticket (10 min)&quot;">​</a></h3><p>The week 5 exit ticket: 🔴 AI off, graded on completion, not correctness. The first question looks back at your week 3 game; answer it from memory, without opening your files.</p><h3 id="troubleshooting-1" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting-1" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Problem</th><th>Try this</th></tr></thead><tbody><tr><td>The AI rewrote my spec anyway</td><td>Don&#39;t use its version. Reply &quot;Please only list questions; don&#39;t rewrite.&quot;</td></tr><tr><td>The fresh chat already seems to know my idea</td><td>Its memory is on. Use a temporary chat, or turn memory off (<a href="./../../setup/privacy-settings.html">privacy settings</a>)</td></tr><tr><td>The Goldfish asked almost nothing</td><td>Ask a follow-up in the same chat: &quot;Which three things would you most likely get wrong if you built this now?&quot;</td></tr><tr><td>The Goldfish asked fifteen questions</td><td>Answer the ones about MUST stories first. Put the rest in Open questions, each with your best guess</td></tr><tr><td>My review partner isn&#39;t here</td><td>Your instructor joins you to another pair, or gives you the practice spec</td></tr><tr><td>&quot;Repository name already exists&quot;</td><td>You already have one with that name. Add a word: <code>plant-tracker-2026</code></td></tr><tr><td>Pages shows my README, not an app</td><td>Expected: there&#39;s no <code>index.html</code> until next week</td></tr><tr><td>There&#39;s no Pages option in Settings</td><td>Check the repository is <strong>Public</strong>. Menus move; ask the assistant where GitHub Pages settings are today</td></tr></tbody></table><hr><h2 id="before-you-leave-studio-b" tabindex="-1">Before you leave Studio B <a class="header-anchor" href="#before-you-leave-studio-b" aria-label="Permalink to &quot;Before you leave Studio B&quot;">​</a></h2><ul><li>☐ <code>SPEC.md</code> and <code>PROMPTS.md</code> are committed in your new public repository, and Pages is switched on.</li><li>☐ Your written spec review is on Canvas, or you know you&#39;ll finish it for homework.</li><li>☐ Homework: <a href="./homework.html">homework</a>. Your spec review and your reflection go on Canvas, written without AI.</li></ul>`,70)])])}const g=e(r,[["render",i]]);export{u as __pageData,g as default};
